"use client";

import { useEffect, useState, type ComponentType } from "react";
import { getGameLineRegistration } from "@/game-lines/registry/game-line-registry";
import type { GameLineBuilderProps } from "@/lib/game-line-contracts/game-line-ui";
import type { PersistedGameLineId } from "@/lib/core/character/game-line-ids";
import { useCatalogSnapshot } from "./catalog-boundary";

/** Loads only the selected line's builder surface through the lightweight registry. */
export function GameLineBuilder(props: GameLineBuilderProps & { gameLine: PersistedGameLineId }) {
  const catalogs = useCatalogSnapshot();
  const [Builder, setBuilder] = useState<ComponentType<GameLineBuilderProps> | null>(null);

  useEffect(() => {
    let cancelled = false;
    void getGameLineRegistration(props.gameLine).loadBuilder().then(({ Component }) => {
      if (!cancelled) setBuilder(() => Component);
    });
    return () => { cancelled = true; };
  }, [props.gameLine]);

  return Builder ? <Builder {...props} fixedGameLine={props.gameLine} catalogs={catalogs} /> : <div className="loading-card">Carregando…</div>;
}

"use client";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { CharacterSheet } from "@/lib/core/character/character-types";
import { useLanguage } from "@/lib/i18n";
import { entitlementPrerequisitesMet, normalizeEntitlementState, type EntitlementAllocation, type EntitlementDefinition, type EntitlementState } from "@/lib/entitlements";
import { normalizeMeritConfiguration } from "@/lib/core/character/merit-configuration";
import { synchronizeChangelingBuilderMeritGrants as synchronizeMeritGrants } from "@/game-lines/changeling/builder-merit-grants";
import { CTL_THREADS, changelingAnchorRecovery } from "@/game-lines/changeling/creation-rules";
import { SKILLS } from "@/lib/core/character/creation-rules";
import { systemTerm } from "@/lib/system-terms";
import { createRandomId } from "@/lib/random-id";
import { RuleSelect } from "./rule-select";
import { ConfirmAction } from "./confirm-action";
export function EntitlementPage({character,updateSheet,catalog}:{character:CharacterSheet;updateSheet:(sheet:CharacterSheet)=>void;catalog:readonly EntitlementDefinition[]}){
  const { locale, t }=useLanguage(),wyrd=Math.max(1,Math.min(10,Number(character.line_data.wyrd??1)));
  const availableEntitlements=catalog;
  const state=normalizeEntitlementState(character.line_data.entitlement,wyrd,availableEntitlements),definition=availableEntitlements.find((item)=>item.id===state.definitionId);
  const save=(nextState:EntitlementState)=>{const next=structuredClone(character);next.line_data={...next.line_data,entitlement:normalizeEntitlementState(nextState,wyrd,availableEntitlements)};const merit=next.merits.find((item)=>item.name==="Entitlement"&&!item.grantedBy);if(merit)merit.configuration={...normalizeMeritConfiguration(merit.configuration),definitionId:nextState.definitionId,roleId:nextState.roleId};updateSheet(synchronizeMeritGrants(next,availableEntitlements));};
  const patch=(next:Partial<EntitlementState>)=>save({...state,...next});
  const choice=(key:string,value:string)=>patch({choices:{...state.choices,[key]:value}});
  const activeBlessings=new Set(state.allocations.filter((item)=>item.target==="blessing").map((item)=>item.blessingId));
  const nextSequence=Math.max(-1,...state.allocations.map((item)=>item.sequence))+1;
  const changeAllocation=(allocation:EntitlementAllocation|undefined,value:string)=>{
    let allocations=state.allocations.filter((item)=>item.id!==allocation?.id);
    if(value!=="none") allocations=[...allocations,value==="token"?{id:allocation?.id??createRandomId(),target:"token",sequence:allocation?.sequence??nextSequence}:{id:allocation?.id??createRandomId(),target:"blessing",blessingId:value.slice(9),sequence:allocation?.sequence??nextSequence}];
    patch({allocations});
  };
  const selectDefinition=(definitionId:string)=>save({...state,definitionId,roleId:"",accepted:false,touchstone:{name:"",status:"active"},allocations:[],choices:{},suspendedBenefitIds:[],token:{rating:0,storedGlamour:0}});
  if(!definition)return <div className="entitlement-page"><h3 className="official-heading"><span>{t("ui.entitlement")}</span></h3><label className="entitlement-select">{t("ui.title")}<Select onValueChange={selectDefinition}><SelectTrigger><SelectValue placeholder={t("ui.selectAnEntitlement")}/></SelectTrigger><SelectContent>{availableEntitlements.map((item)=><SelectItem key={item.id} value={item.id}>{item.name} · {item.meritName}</SelectItem>)}</SelectContent></Select></label></div>;
  const role=definition.roles?.find((item)=>item.id===state.roleId),prerequisitesMet=entitlementPrerequisitesMet(definition,state,character);
  const conditional=definition.blessings.filter((item)=>item.conditional&&activeBlessings.has(item.id));
  const tokenCount=state.allocations.filter((item)=>item.target==="token").length,canAccept=prerequisitesMet&&state.touchstone.status==="active"&&Boolean(state.touchstone.name.trim()),operational=state.accepted&&canAccept;
  const allocationRows=[...state.allocations,...(state.allocations.length<wyrd?[undefined]:[])];
  return <div className="entitlement-page">
    <header className="entitlement-title"><div><h2>{definition.name}</h2><p>{definition.meritName} •••• · {definition.sourceCode} p. {definition.page}</p></div>{state.accepted?<ConfirmAction trigger={<Button type="button" size="sm" variant="destructive">{t("ui.removeEntitlement")}</Button>} title={t("ui.removefc5df2", { p1: definition.name })} description={t("ui.theEntitlementItsRanksBlessingsHeraldryAndAll")} action={t("ui.removeEntitlement")} onConfirm={()=>save({...state,accepted:false,allocations:[],choices:{},suspendedBenefitIds:[],token:{rating:0,storedGlamour:0}})}/>:<Button type="button" size="sm" disabled={!canAccept} onClick={()=>patch({accepted:true})}>{t("ui.acceptEntitlement")}</Button>}</header>
    {!state.accepted&&<label className="entitlement-select">{t("ui.title")}<Select value={definition.id} onValueChange={selectDefinition}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{availableEntitlements.map((item)=><SelectItem key={item.id} value={item.id}>{item.name} · {item.meritName}</SelectItem>)}</SelectContent></Select></label>}
    {!state.accepted&&definition.roles&&<label className="entitlement-select">{t("ui.role")}<Select value={state.roleId||undefined} onValueChange={(roleId)=>patch({roleId})}><SelectTrigger><SelectValue placeholder={t("ui.selectARole")}/></SelectTrigger><SelectContent>{definition.roles.map((item)=><SelectItem key={item.id} value={item.id}>{item.name} · {item.prerequisites}</SelectItem>)}</SelectContent></Select></label>}
    <p className={`entitlement-prerequisites ${prerequisitesMet?"met":"unmet"}`}><strong>{t("ui.prerequisites")}:</strong> {role?`${definition.prerequisites} ${role.name}: ${role.prerequisites}.`:definition.prerequisites}</p>
    <section className={`entitlement-touchstone${state.touchstone.name.trim()?"":" missing"}`}><h3>{t("ui.entitlementTouchstone")}</h3><p>{definition.touchstone}</p><div className="entitlement-choice-row"><Input value={state.touchstone.name} onChange={(event)=>patch({touchstone:{...state.touchstone,name:event.target.value}})} placeholder={t("ui.touchstoneName")}/><RuleSelect value={state.touchstone.status} onChange={(status)=>patch({touchstone:{...state.touchstone,status:status as EntitlementState["touchstone"]["status"]}})} options={[{value:"active",label:t("ui.active")},{value:"lost",label:t("ui.lost")},{value:"suspended",label:t("ui.suspended")} ]}/></div></section>
    <div className="entitlement-overview"><section><h3>{t("ui.purpose")}</h3><p>{definition.purpose}</p></section><section><h3>{t("ui.privileges")}</h3><p>{definition.privileges}</p>{role&&<p><strong>{role.name}:</strong> {role.privilege}</p>}</section><section><h3>{t("ui.duties")}</h3><p>{definition.duties}</p>{role&&<p><strong>{role.name}:</strong> {role.duties}</p>}</section><section><h3>{t("ui.maskAndMien")}</h3><p>{definition.maskAndMien}</p></section></div>
    {definition.id==="baron-lesser-ones"&&state.allocations.length>=2&&<label className="entitlement-select">{t("ui.goblinFeaturesUpTo", { p1: Math.floor(state.allocations.length/2) })}<textarea value={state.choices["goblin-features"]??""} onChange={(event)=>choice("goblin-features",event.target.value)} placeholder={t("ui.oneFeaturePerLine")}/></label>}
    {definition.id==="dauphines-wayward-children"&&<label className="entitlement-select">{t("ui.currentWards")}<textarea value={state.choices.wards??""} onChange={(event)=>choice("wards",event.target.value)} placeholder={t("ui.oneWardPerLine")}/></label>}
    <section className="entitlement-inherent"><h3>{t("ui.inherentPrivilege")}</h3><p>{t("ui.spend1GlamourFor2ToAMundane")}</p></section>
    {state.accepted&&!canAccept&&<p className="entitlement-inactive">{t("ui.theEntitlementIsInactiveWhileItsPrerequisitesOr")}</p>}
    <section><h3>{t("ui.entitlementRanks")} · {state.allocations.length}/{wyrd}</h3><div className="entitlement-allocations">{allocationRows.map((allocation,index)=>{const current=allocation?.target==="token"?"token":allocation?.blessingId?`blessing:${allocation.blessingId}`:"none";return <label key={allocation?.id??"new"}>{t("ui.rank")} {index+1}<Select disabled={!state.accepted} value={current} onValueChange={(value)=>changeAllocation(allocation,value)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">{t("ui.unallocated")}</SelectItem>{(current==="token"||tokenCount<5)&&<SelectItem value="token">{t("ui.heraldryToken")}</SelectItem>}{definition.blessings.filter((item)=>current===`blessing:${item.id}`||!activeBlessings.has(item.id)).map((item)=><SelectItem key={item.id} value={`blessing:${item.id}`}>{item.name}</SelectItem>)}</SelectContent></Select></label>;})}</div></section>
    <section><h3>{t("ui.blessings")}</h3><div className="entitlement-blessings">{definition.blessings.filter((blessing)=>!state.accepted||activeBlessings.has(blessing.id)).map((blessing)=>{const active=activeBlessings.has(blessing.id),suspended=state.suspendedBenefitIds.includes(blessing.id);return <article key={blessing.id} className={`${active?"active":""} ${suspended||active&&!operational?"suspended":""}`}><header><strong>{blessing.name}</strong><span>{active?t("ui.acquired"):t("ui.notAcquired")}{blessing.conditional?" · Conditional":""}</span></header><p>{blessing.description}</p>{active&&blessing.id==="inherited-expertise"&&<div className="entitlement-choice-row"><RuleSelect value={state.choices["inherited-expertise-skill"]??""} onChange={(value)=>choice("inherited-expertise-skill",value)} options={Object.values(SKILLS).flat().map((name)=>({value:name,label:systemTerm(name,"en-US")}))}/><Input value={state.choices["inherited-expertise-name"]??""} onChange={(event)=>choice("inherited-expertise-name",event.target.value)} placeholder={t("ui.specialty")}/></div>}{active&&blessing.id==="inherited-token"&&<div className="entitlement-token-fields">{[["name","Name"],["cost","Cost"],["effect","Effect"],["catch","Catch"],["drawback","Drawback"]].map(([key,label])=><label key={key}>{label}<Input value={state.choices[`inherited-token-${key}`]??""} onChange={(event)=>choice(`inherited-token-${key}`,event.target.value)}/></label>)}</div>}{active&&blessing.id==="hidden-library"&&<RuleSelect value={state.choices[blessing.id]??""} onChange={(value)=>choice(blessing.id,value)} options={SKILLS.Mental.map((name)=>({value:name,label:systemTerm(name,"en-US")}))}/>} {active&&blessing.id==="predecessors-thread"&&<label>{blessing.choiceLabel}<RuleSelect value={state.choices[blessing.id]??""} onChange={(value)=>choice(blessing.id,value)} options={CTL_THREADS.map((name)=>({value:name,label:systemTerm(name,locale)}))}/>{state.choices[blessing.id]&&<small className="entitlement-choice-help">{changelingAnchorRecovery("thread",state.choices[blessing.id],locale)}</small>}</label>}{active&&blessing.choiceLabel&&!['inherited-expertise','inherited-token','hidden-library','predecessors-thread'].includes(blessing.id)&&<label>{blessing.choiceLabel}<Input value={state.choices[blessing.id]??""} onChange={(event)=>choice(blessing.id,event.target.value)}/></label>}</article>;})}</div></section>
    <section className={`entitlement-heraldry${operational?"":" entitlement-disabled"}`}><h3>{t("ui.heraldry")} · {definition.token.name} {"•".repeat(tokenCount)}</h3><p><strong>{definition.heraldry}</strong> {definition.token.description}</p>{role&&<p><strong>{role.heraldryColor}:</strong> {role.tokenBonus} Drawback: {role.tokenDrawback}.</p>}<p><strong>{t("combat.effectLabel")}</strong> {definition.token.effect}</p><p><strong>Catch:</strong> {definition.token.catch}</p><p><strong>Drawback:</strong> {definition.token.drawback}</p></section>
    {conditional.length>0&&<section><h3>{t("ui.conditionalBenefits")}</h3><p>{t("ui.suspendOnlyTheBenefitsTheStorytellerDeterminedWere")}</p>{conditional.map((item)=><label className="entitlement-suspension" key={item.id}><input type="checkbox" checked={state.suspendedBenefitIds.includes(item.id)} onChange={(event)=>patch({suspendedBenefitIds:event.target.checked?[...state.suspendedBenefitIds,item.id]:state.suspendedBenefitIds.filter((id)=>id!==item.id)})}/>{t("ui.suspend")} {item.name}</label>)}</section>}
    <div className="entitlement-overview"><section><h3>{t("ui.curse")}</h3><p>{definition.curse}</p><p><strong>{t("ui.currentAdditionalDice")}:</strong> +{state.allocations.length}</p></section><section><h3>{t("ui.beat")}</h3><p>{definition.beat}</p>{definition.id==="master-of-keys"&&state.allocations.length>0&&<label className="stored-glamour">{t("ui.additionalAspiration")}<Input value={state.choices["dangerous-secret-aspiration"]??""} onChange={(event)=>choice("dangerous-secret-aspiration",event.target.value)} placeholder={t("ui.pursueADangerousSecret")}/></label>}</section></div>
    <section><h3>{t("ui.legends")}</h3><ul>{definition.legends.map((legend)=><li key={legend}>{legend}</li>)}</ul></section>
  </div>;
}

"use client";

import { useEffect, useState, type ComponentType } from "react";
import { getGameLineRegistration } from "@/game-lines/registry/game-line-registry";
import type { GameLineSheetProps } from "@/lib/game-line-contracts/game-line-ui";
import { useCatalogSnapshot } from "../catalog-boundary";

/** Loads only the active line's in-app sheet surface through the registry. */
export function GameLineSheet(props: GameLineSheetProps) {
  const catalogs = useCatalogSnapshot();
  const [Sheet, setSheet] = useState<ComponentType<GameLineSheetProps> | null>(null);

  useEffect(() => {
    let cancelled = false;
    void getGameLineRegistration(props.character.game_line).loadSheet().then(({ Component }) => {
      if (!cancelled) setSheet(() => Component);
    });
    return () => { cancelled = true; };
  }, [props.character.game_line]);

  return Sheet ? <Sheet {...props} catalogs={catalogs} /> : <div className="loading-card">Carregando…</div>;
}

"use client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { AlertDialog,AlertDialogAction,AlertDialogCancel,AlertDialogContent,AlertDialogDescription,AlertDialogFooter,AlertDialogHeader,AlertDialogTitle } from "@/components/ui/alert-dialog";
import type { CharacterSheet } from "@/lib/core/character/character-types";
import { useLanguage } from "@/lib/i18n";
import { findLegacy,LEGACIES,legacyAttainmentPrerequisites,legacyEntryPrerequisites,normalizeLegacyState } from "@/lib/legacies";
import type { MageAdvancementUndo } from "@/lib/experience-refunds";
import { discardLegacyAdvancements } from "@/lib/legacy-progression";
import { createRandomId } from "@/lib/random-id";
import { RuleSelect } from "./rule-select";

type MageXpEntry={undo?:MageAdvancementUndo;id:string;description:string;regular:number;arcane:number;createdAt:string;before:{attributes:Record<string,number>;skills:Record<string,number>;merits:CharacterSheet["merits"];specializations:CharacterSheet["specializations"];line_data:Record<string,unknown>}};

export function LegacyPage({character,updateSheet,onDiscard}:{character:CharacterSheet;updateSheet:(sheet:CharacterSheet)=>void;onDiscard:()=>void}){
 const { t }=useLanguage(),state=normalizeLegacyState(character.line_data.legacy_state),definition=findLegacy(state.definitionId),checks=definition?legacyEntryPrerequisites(character,definition):undefined;
 const [method,setMethod]=useState<"tutelage"|"daimonomikon"|"soul-study">("tutelage"),[pool,setPool]=useState<"regular"|"arcane">("regular"),[training,setTraining]=useState<"tutor"|"self">("tutor"),[feedback,setFeedback]=useState(""),[discardOpen,setDiscardOpen]=useState(false);
 const regular=Number(character.current_state.mage_experience_available??0),arcane=Number(character.current_state.arcane_experience_available??0),gnosis=Number(character.line_data.gnosis??1);
 const history=Array.isArray(character.current_state.mage_experience_history)?character.current_state.mage_experience_history as MageXpEntry[]:[];
 const selectLegacy=(definitionId:string)=>{const next=structuredClone(character);next.line_data.legacy_state={definitionId,joined:false,attainmentRanks:[],initiationMethod:""};updateSheet(next);setFeedback("");};
 const findPraxis=(name:string)=>{for(const key of ["praxes","learned_praxes"] as const){const list=Array.isArray(character.line_data[key])?character.line_data[key] as Record<string,unknown>[]:[];const index=list.findIndex(item=>String(item.originalName??item.name)===name);if(index>=0)return {key,index,item:list[index]};}};
 const removePraxis=(next:CharacterSheet,praxis:ReturnType<typeof findPraxis>)=>{if(!praxis)return;const list=[...(next.line_data[praxis.key] as Record<string,unknown>[])];list.splice(praxis.index,1);next.line_data[praxis.key]=list;};
 const savePurchase=(next:CharacterSheet,description:string,regularCost:number,arcaneCost:number,undo:MageAdvancementUndo,credits:{regular?:number;arcane?:number;beats?:number}={})=>{const creditedRegular=Number(credits.regular??0),creditedArcane=Number(credits.arcane??0),creditedArcaneBeats=Number(credits.beats??0),finalUndo={...undo,creditedRegular,creditedArcane,creditedArcaneBeats} as MageAdvancementUndo;const entry:MageXpEntry={id:createRandomId(),description,regular:regularCost,arcane:arcaneCost,createdAt:new Date().toISOString(),undo:finalUndo,before:{attributes:structuredClone(character.attributes),skills:structuredClone(character.skills),merits:structuredClone(character.merits),specializations:structuredClone(character.specializations),line_data:structuredClone(character.line_data)}};next.current_state={...next.current_state,mage_experience_available:regular-regularCost+creditedRegular,arcane_experience_available:arcane-arcaneCost+creditedArcane,mage_experience_spent:Number(next.current_state.mage_experience_spent??0)+regularCost,arcane_experience_spent:Number(next.current_state.arcane_experience_spent??0)+arcaneCost,arcane_experience_beats:Number(next.current_state.arcane_experience_beats??0)+creditedArcaneBeats,mage_experience_history:[entry,...history].slice(0,100)};updateSheet(next);};
 const join=()=>{if(!definition||!checks?.met)return setFeedback(t("ui.theLegacyPrerequisitesAreNotYetMet"));const regularCost=method==="tutelage"&&pool==="regular"?1:0,arcaneCost=regularCost?0:1;if(regular<regularCost||arcane<arcaneCost)return setFeedback(t("ui.insufficientExperience"));const praxis=findPraxis(definition.entryPraxis),alternative=!checks.parentage&&checks.praxis,credits=praxis?{regular:alternative?1:0,arcane:alternative?0:1,beats:1+(method==="tutelage"?1:0)}:{beats:method==="tutelage"?1:0},next=structuredClone(character);removePraxis(next,praxis);next.line_data.legacy_state={definitionId:definition.id,joined:true,attainmentRanks:[1],initiationMethod:method};savePurchase(next,`${definition.name} · Initiation`,regularCost,arcaneCost,{kind:"legacyInitiation",previousState:character.line_data.legacy_state,removedPraxis:praxis,creditedRegular:0,creditedArcane:0,creditedArcaneBeats:0},credits);};
 const nextRank=Math.max(1,...state.attainmentRanks)+1,attainment=definition?.attainments.find(item=>item.rank===nextRank),rankMet=Boolean(definition&&attainment&&legacyAttainmentPrerequisites(character,definition,attainment.rank));
 const buyAttainment=()=>{if(!definition||!attainment||!rankMet)return setFeedback(t("ui.theNextAttainmentSPrerequisitesAreNotYet"));const effective=training==="self"?"arcane":pool,regularCost=effective==="regular"?1:0,arcaneCost=effective==="arcane"?1:0;if(regular<regularCost||arcane<arcaneCost)return setFeedback(t("ui.insufficientExperience"));const praxis=findPraxis(attainment.praxisName??""),next=structuredClone(character);removePraxis(next,praxis);next.line_data.legacy_state={...state,attainmentRanks:[...state.attainmentRanks,attainment.rank]};savePurchase(next,`${definition.name} · ${attainment.name}`,regularCost,arcaneCost,{kind:"legacyAttainment",rank:attainment.rank,removedPraxis:praxis,creditedRegular:0,creditedArcane:0,creditedArcaneBeats:0},praxis?{arcane:1,beats:1}:{});};
 const discard=()=>{updateSheet(discardLegacyAdvancements(character));onDiscard();};
 const choices=LEGACIES.map(item=>({value:item.id,label:`${item.name} · ${item.source} · p. ${item.page}`}));
 if(!definition)return <div className="entitlement-page legacy-page"><header className="entitlement-title"><div><h2>{t("ui.legacy")}</h2><p>{t("ui.selectAnAvailableLegacy")}</p></div></header><section className="legacy-selector"><RuleSelect value="__select" onChange={value=>value!=="__select"&&selectLegacy(value)} options={[{value:"__select",label:t("ui.selectLegacy")},...choices]}/></section></div>;
 const pageLabel=definition.id==="the-eleventh-question"?`${definition.page}–202`:String(definition.page);
 return <div className="entitlement-page legacy-page">
  <header className="entitlement-title legacy-title"><div><h2>{definition.name}</h2><p>{definition.source} · p. {pageLabel} · {t("ui.rulingArcanum")}: {definition.rulingArcanum}</p></div>{state.joined?<Button type="button" size="sm" variant="destructive" onClick={()=>setDiscardOpen(true)}>{t("ui.discardLegacy")}</Button>:<Button type="button" size="sm" className="builder-add-action legacy-join-button" disabled={!checks?.met} onClick={join}>{t("ui.joinLegacy")}</Button>}</header>
  {!state.joined&&<div className="legacy-selector"><RuleSelect value={definition.id} onChange={selectLegacy} options={choices}/></div>}
  {(!state.joined||attainment)&&<p className={`entitlement-prerequisites ${state.joined?(rankMet?"met":"unmet"):(checks?.met?"met":"unmet")}`}><strong>{t("ui.prerequisites")}:</strong> {state.joined?attainment?.prerequisites:definition.prerequisites}</p>}
  <section className="legacy-reference"><h3>{t("ui.legacyInformation")}</h3><ul><li>{t("ui.tutorAndStudentHaveAStrongSympatheticLink")}</li><li>{t("ui.afterASignificantMysticalEmotionalOrIntimateInteraction")}</li><li>{t("ui.membersDaimonomikaAndSoulStonesOfTheSame")}</li></ul><small>{t("ui.theSheetDoesNotTrackTheseRulesAutomatically")}</small></section>
  {!state.joined&&<section className="legacy-join"><div className="legacy-requirement-list">{checks?.items.map(item=><span className={item.met?"met":"unmet"} key={item.label}>{item.met?"✓":"×"} {item.label}</span>)}</div><div className="legacy-join-controls"><label>{t("ui.initiationMethod")}<RuleSelect value={method} onChange={value=>{const next=value as typeof method;setMethod(next);if(next!=="tutelage")setPool("arcane");}} options={[{value:"tutelage",label:"Tutelage"},{value:"daimonomikon",label:"Daimonomikon"},{value:"soul-study",label:"Soul or Soul Stone Study"}]}/></label><label>{t("ui.payment")}<RuleSelect value={method==="tutelage"?pool:"arcane"} onChange={value=>setPool(value as typeof pool)} options={method==="tutelage"?[{value:"regular",label:"1 Experience"},{value:"arcane",label:"1 Arcane Experience"}]:[{value:"arcane",label:"1 Arcane Experience"}]}/></label></div>{gnosis>=3&&<details className="experience-rules"><summary>{t("ui.createALegacy")}</summary><p>{t("ui.gnosis3PermitsFoundingALegacyFor1")}</p></details>}</section>}
  {state.joined&&attainment&&<section className="legacy-join legacy-next-attainment"><div className="legacy-attainment-purchase"><p><strong>{t("ui.nextAttainment")}:</strong> {attainment.name} · 1 Experience</p><RuleSelect value={training} onChange={value=>{const next=value as typeof training;setTraining(next);if(next==="self")setPool("arcane");}} options={[{value:"tutor",label:t("ui.learnFromATutor")},{value:"self",label:t("ui.developWithoutATutor")}]}/>{training==="tutor"&&<RuleSelect value={pool} onChange={value=>setPool(value as typeof pool)} options={[{value:"regular",label:"1 Experience"},{value:"arcane",label:"1 Arcane Experience"}]}/>}<Button type="button" size="sm" disabled={!rankMet} onClick={buyAttainment}>{t("ui.purchaseAttainment")}</Button></div></section>}
  <div className="entitlement-overview">{!state.joined&&<section><h3>{t("ui.initiation")}</h3><p>{definition.initiation}</p></section>}<section><h3>{t("ui.organization")}</h3><p>{definition.organization}</p></section><section><h3>{t("ui.theory")}</h3><p>{definition.theory}</p></section></div>
  <div className="entitlement-overview"><section><h3>{t("ui.yantras")}</h3><ul>{definition.yantras.map(item=><li key={item}>{item}</li>)}</ul></section><section><h3>{t("ui.oblations")}</h3><ul>{definition.oblations.map(item=><li key={item}>{item}</li>)}</ul></section></div>
  <section><h3>{t("ui.attainments")}</h3><div className="entitlement-blessings legacy-attainments">{definition.attainments.map(item=>{const acquired=state.attainmentRanks.includes(item.rank);return <details key={item.rank} className={acquired?"active":""}><summary><strong>{item.rank}. {item.name}</strong><span>{acquired?t("ui.acquiredb5d1a8"):item.prerequisites}</span></summary><p>{item.description}</p>{item.optional&&<p><strong>Optional:</strong> {item.optional}</p>}</details>})}</div></section>
  {feedback&&<p className="experience-feedback">{feedback}</p>}
  <AlertDialog open={discardOpen} onOpenChange={setDiscardOpen}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{t("ui.discard", { p1: definition.name })}</AlertDialogTitle><AlertDialogDescription>{t("ui.theLegacyAndAllAcquiredAttainmentsWillBe")}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel size="sm" className="catalog-dialog-done">{t("ui.cancel")}</AlertDialogCancel><AlertDialogAction size="sm" className="catalog-dialog-done" variant="destructive" onClick={discard}>{t("ui.discardLegacy")}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 </div>;
}

